import React from "react";

const Home = () => {
  return (
    <div className="min-h-screen w-full bg-gradient-to-br from-pink-100 via-pink-50 to-blue-100 flex flex-col items-center justify-center px-6 py-12 text-center">
      {/* Heading */}
      <h1 className="text-4xl md:text-5xl font-extrabold text-pink-600 mb-8 drop-shadow-lg">
        🌈 Welcome to the Online Gamification System
      </h1>

      {/* Hero Image */}
      <img
        src="https://cdn.pixabay.com/photo/2017/02/02/15/15/kids-2030269_1280.png"
        alt="Fun Learning"
        className="w-64 md:w-96 rounded-3xl shadow-lg border-4 border-pink-300"
      />
    </div>
  );
};

export default Home;
